mapper.select:
select t.ls_id,t.ls_id lsId,t.machine_id,t.machine_id machineId,t.log_id,t.log_id logId,t.status_cd,t.status_cd
statusCd,t.community_id,t.community_id communityId,t.sensor_value,t.sensor_value
sensorValue,t.sensor_id,t.sensor_id sensorId
from instrument_log_sensor t
where 1 =1

    and t.ls_id= #{lsId}


    and t.machine_id= #{machineId}


    and t.log_id= #{logId}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.sensor_value= #{sensorValue}


    and t.sensor_id= #{sensorId}

order by t.create_time desc

    limit #{page}, #{row}

